generation_id=#{generationId}
AND source_channel IN
#{value}

    AND COALESCE(NULLIF(function_module,''),'UNKNOWN') IN
    #{value}


    AND (province_code IN
    #{value}
    OR city_code IN
    #{value})


    AND source_channel IN
    #{value}


    AND (source_record_id LIKE #{criteria.keywordPattern} ESCAPE '=' OR title LIKE #{criteria.keywordPattern} ESCAPE '='
         OR description LIKE #{criteria.keywordPattern} ESCAPE '=')


    AND COALESCE(severity_level,ai_severity,'UNKNOWN') IN
    #{value}


    AND processing_status IN
    #{value}


    AND COALESCE(NULLIF(function_module,''),'UNKNOWN') IN
    #{value}


    AND COALESCE(NULLIF(issue_category,''),'UNKNOWN') IN
    #{value}


    AND COALESCE(NULLIF(reproducibility,''),'UNKNOWN') IN
    #{value}

AND ai_review_status=#{criteria.aiReviewStatus}
AND COALESCE(NULLIF(province_code,''),'UNKNOWN')=#{criteria.province}
AND COALESCE(NULLIF(city_code,''),'UNKNOWN')=#{criteria.city}
AND owner_user_id=#{criteria.ownerId}
AND owner_user_id IS NULL
AND handoff_pending=TRUE
AND reported_at>=#{criteria.startTime}
AND reported_at<=#{criteria.endTime}
AND COALESCE(channel_app_id,station_app_id)=#{criteria.appId}
AND COALESCE(package_name,channel_package_name)=#{criteria.packageName}
AND channel_device_model LIKE #{criteria.deviceModelPattern} ESCAPE '='
AND channel_os_version LIKE #{criteria.osVersionPattern} ESCAPE '='
AND channel_network_type=#{criteria.networkType}
AND app_version=#{criteria.appVersion}
AND jira_project_key=#{criteria.projectKey}
AND jira_key=#{criteria.issueKey}
AND jira_issue_type=#{criteria.issueType}
AND jira_priority=#{criteria.priority}
AND jira_assignee=#{criteria.assignee}
AND jira_resolution=#{criteria.resolution}
AND quality_repair_region LIKE #{criteria.repairRegionPattern} ESCAPE '='
AND quality_application_type=#{criteria.applicationType}
AND quality_exchange_request=#{criteria.exchangeRequest}

    AND (import_batch_code=#{criteria.importBatchCode}
         OR JSON_CONTAINS(jira_import_batch_codes,JSON_QUOTE(#{criteria.importBatchCode})))


    AND COALESCE(redblack_source_platform,station_source_platform)=#{criteria.sourcePlatform}

AND user_sentiment=#{criteria.emotionType}
AND redblack_keyword=#{criteria.channelKeyword}
AND redblack_list_type=#{criteria.listType}
AND station_product_id=#{criteria.productId}
AND station_source_sub_channel=#{criteria.sourceSubChannel}
AND station_api_version=#{criteria.apiVersion}

    AND (COALESCE(package_name,channel_package_name) IS NULL OR NULLIF(app_version,'') IS NULL)


    AND (COALESCE(package_name,channel_package_name) IS NOT NULL AND NULLIF(app_version,'') IS NOT NULL)


    AND (jira_resolved_at IS NOT NULL OR UPPER(COALESCE(jira_status,'')) IN ('RESOLVED','CLOSED','DONE'))


    AND NOT (jira_resolved_at IS NOT NULL OR UPPER(COALESCE(jira_status,'')) IN ('RESOLVED','CLOSED','DONE'))
